package com.ilia.gikashvili.archmain.version.service;
import com.ilia.gikashvili.archmain.version.entity.ArchitectureVersion;
import com.ilia.gikashvili.archmain.version.repository.ArchitectureVersionRepository;
import com.ilia.gikashvili.archmain.version.dto.VersionRequest;
import com.ilia.gikashvili.archmain.architecture.service.ArchitectureService;
import com.ilia.gikashvili.archmain.architecture.mapper.ArchitectureMapper;
import com.ilia.gikashvili.archmain.architecture.model.*;
import com.ilia.gikashvili.archmain.access.service.ProjectAccessService;
import com.ilia.gikashvili.archmain.access.policy.Permission;
import com.ilia.gikashvili.archmain.common.exception.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.function.Function;
@Service
@Transactional
public class VersionService {
 private final com.ilia.gikashvili.archmain.user.repository.UserRepository users; private final com.ilia.gikashvili.archmain.branch.service.BranchService branches; private final ArchitectureVersionRepository repo;private final ArchitectureService architecture;private final ArchitectureMapper mapper;private final ProjectAccessService access;
 public VersionService(ArchitectureVersionRepository repo,ArchitectureService architecture,ArchitectureMapper mapper,ProjectAccessService access,com.ilia.gikashvili.archmain.user.repository.UserRepository users,com.ilia.gikashvili.archmain.branch.service.BranchService branches){this.users=users;this.branches=branches;this.repo=repo;this.architecture=architecture;this.mapper=mapper;this.access=access;}
 public List<ArchitectureVersion> list(UUID pid,UUID user){access.require(pid,user,Permission.READ);return repo.findByProjectIdOrderByCreatedAtDesc(pid);}
 public ArchitectureVersion get(UUID id,UUID user,Permission permission){var v=repo.findById(id).orElseThrow(()->new NotFoundException("Version",id));access.require(v.getProjectId(),user,permission);return v;}
 public ArchitectureVersion create(UUID pid,UUID user,VersionRequest r){if(pid==null)throw new ValidationException("Project id is required");access.require(pid,user,Permission.EDIT);var e=architecture.getByProjectId(pid,user);var v=new ArchitectureVersion();v.setProjectId(pid);v.setCreatedBy(user);v.setSourceRevision(e.getRevision());v.setDocumentJson(e.getDocumentJson());if(r.branchId()!=null){var b=branches.get(r.branchId(),user,Permission.READ);if(!b.projectId.equals(pid))throw new ValidationException("Branch belongs to another project");v.branchId=b.getId();v.branchName=b.name;v.setDocumentJson(b.documentJson);v.setSourceRevision(b.revision);}v.parentVersionId=list(pid,user).stream().filter(x->Objects.equals(x.branchId,v.branchId)).findFirst().map(ArchitectureVersion::getId).orElse(null);apply(v,r);return repo.saveAndFlush(v);}
 private void apply(ArchitectureVersion v,VersionRequest r){if(r.name()!=null){if(r.name().isBlank())throw new ValidationException("Name is required");v.setName(r.name());}if(v.getName()==null&&r.message()!=null)v.setName(r.message().substring(0,Math.min(200,r.message().length())));if(r.message()!=null)v.message=r.message();if(v.getName()==null)throw new ValidationException("Name is required");if(r.description()!=null)v.setDescription(r.description());}
 public ArchitectureVersion patch(UUID id,UUID user,VersionRequest r){var v=get(id,user,Permission.EDIT);apply(v,r);return repo.saveAndFlush(v);}
 public void delete(UUID id,UUID user){repo.delete(get(id,user,Permission.EDIT));}
 public ArchitectureDocument document(ArchitectureVersion v){var e=new com.ilia.gikashvili.archmain.architecture.entity.ArchitectureDocumentEntity();e.setDocumentJson(v.getDocumentJson());return mapper.toModel(e);}
 public Object restore(UUID id,UUID user){var v=get(id,user,Permission.EDIT);var e=architecture.getByProjectId(v.getProjectId(),user);return mapper.toResponse(architecture.save(v.getProjectId(),user,document(v),e.getRevision()));}
 public Map<String,Object> response(ArchitectureVersion v){Map<String,Object> r=new LinkedHashMap<>();r.put("id",v.getId());r.put("projectId",v.getProjectId());r.put("name",v.getName());r.put("description",v.getDescription());r.put("createdBy",v.getCreatedBy());r.put("sourceRevision",v.getSourceRevision());r.put("createdAt",v.getCreatedAt());r.put("updatedAt",v.getUpdatedAt());r.put("message",v.message==null?v.getName():v.message);Map<String,Object> author=new LinkedHashMap<>();author.put("id",v.getCreatedBy());author.put("name",users.findById(v.getCreatedBy()).map(x->x.getDisplayName()).orElse("Unknown"));r.put("author",author);r.put("parentVersionId",v.parentVersionId);Map<String,Object> branch=new LinkedHashMap<>();branch.put("id",v.branchId);branch.put("name",v.branchName==null?"main":v.branchName);r.put("branch",branch);var delta=parentDiff(v);Map<String,Object> counts=new LinkedHashMap<>();delta.forEach((kind,value)->{Map<String,Object> c=new LinkedHashMap<>();value.forEach((k,l)->c.put(k,((List<?>)l).size()));counts.put(kind,c);});r.put("changeSummary",counts);return r;}
 public Object compare(UUID from,UUID to,UUID user){if(from==null||to==null)throw new ValidationException("Both version ids are required");var a=get(from,user,Permission.READ);var b=get(to,user,Permission.READ);if(!a.getProjectId().equals(b.getProjectId()))throw new ValidationException("Versions must belong to the same project");var da=document(a);var db=document(b);return Map.of("fromVersionId",from,"toVersionId",to,"nodes",diff(da.nodes(),db.nodes(),NodeModel::id),"edges",diff(da.edges(),db.edges(),EdgeModel::id));}
 public Map<String,Map<String,Object>> parentDiff(ArchitectureVersion v){var before=v.parentVersionId==null?ArchitectureDocument.empty():repo.findById(v.parentVersionId).map(this::document).orElse(ArchitectureDocument.empty());var after=document(v);return Map.of("nodes",diff(before.nodes(),after.nodes(),NodeModel::id),"edges",diff(before.edges(),after.edges(),EdgeModel::id));}
 public ArchitectureVersion scoped(UUID pid,UUID vid,UUID user,Permission permission){var v=get(vid,user,permission);if(!v.getProjectId().equals(pid))throw new NotFoundException("Version",vid);return v;}
 private <T> Map<String,Object> diff(List<T> from,List<T> to,Function<T,String> id){Map<String,T> a=new LinkedHashMap<>(),b=new LinkedHashMap<>();from.forEach(v->a.put(id.apply(v),v));to.forEach(v->b.put(id.apply(v),v));List<T> added=new ArrayList<>(),removed=new ArrayList<>();List<Object> changed=new ArrayList<>();b.forEach((k,v)->{if(!a.containsKey(k))added.add(v);else if(!Objects.equals(a.get(k),v))changed.add(Map.of("id",k,"before",a.get(k),"after",v));});a.forEach((k,v)->{if(!b.containsKey(k))removed.add(v);});return Map.of("added",added,"removed",removed,"changed",changed);}
}
